# Let's try using the MSBuild API directly via a small C# script to read the binlog
cat > /tmp/ReadBinlog.csproj << 'EOF'
<Project Sdk="Microsoft.NET.Sdk">
  <PropertyGroup>
    <OutputType>Exe</OutputType>
    <TargetFramework>net9.0</TargetFramework>
  </PropertyGroup>
  <ItemGroup>
    <PackageReference Include="MSBuild.StructuredLogger" Version="2.2.206" />
  </ItemGroup>
</Project>
EOF

cat > /tmp/ReadBinlog.cs << 'EOF'
using System;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Find all errors
var errors = build.FindChildrenRecursive<Error>().ToList();
var warnings = build.FindChildrenRecursive<Warning>().Where(w => w.Text != null && (w.Text.Contains("error") || w.Text.Contains("fail"))).Take(20).ToList();

Console.WriteLine($"=== BUILD ERRORS ({errors.Count} total) ===\n");

foreach (var error in errors)
{
    var project = GetProject(error);
    Console.WriteLine($"Project: {project}");
    Console.WriteLine($"File: {error.File}({error.LineNumber},{error.ColumnNumber})");
    Console.WriteLine($"Code: {error.Code}");
    Console.WriteLine($"Message: {error.Text}");
    Console.WriteLine("---");
}

string GetProject(BaseNode node)
{
    var current = node;
    while (current != null)
    {
        if (current is Project p) return p.Name;
        current = current.Parent as BaseNode;
    }
    return "Unknown";
}
EOF

