cat > /tmp/ReadBinlog2.cs << 'EOF'
using System;
using System.Linq;
using System.Collections.Generic;
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Get all projects
var projects = build.FindChildrenRecursive<Project>().ToList();
Console.WriteLine($"=== PROJECTS IN BUILD ({projects.Count}) ===\n");
foreach (var p in projects)
{
    Console.WriteLine($"  {p.Name} - Succeeded: {p.Succeeded}");
}

// Check for project dependency failures
Console.WriteLine("\n=== FAILED PROJECTS ===\n");
foreach (var p in projects.Where(p => !p.Succeeded))
{
    Console.WriteLine($"  {p.Name}");
    var errors = p.FindChildrenRecursive<Error>().ToList();
    foreach (var e in errors)
    {
        if (!string.IsNullOrEmpty(e.Code))
            Console.WriteLine($"    [{e.Code}] {e.Text}");
    }
}

// Look for the source file content in messages
Console.WriteLine("\n=== LOOKING FOR PACKAGE REFERENCES ===\n");
var messages = build.FindChildrenRecursive<Message>().Where(m => m.Text != null && m.Text.Contains("Newtonsoft")).Take(10).ToList();
foreach (var m in messages)
{
    Console.WriteLine($"  {m.Text?.Substring(0, Math.Min(200, m.Text.Length))}");
}

// Check resolved references
Console.WriteLine("\n=== PACKAGE RESTORE INFO ===\n");
var restoreMessages = build.FindChildrenRecursive<Message>().Where(m => m.Text != null && (m.Text.Contains("PackageReference") || m.Text.Contains("package reference"))).Take(10).ToList();
foreach (var m in restoreMessages)
{
    Console.WriteLine($"  {m.Text?.Substring(0, Math.Min(200, m.Text.Length))}");
}
EOF

