Console.WriteLine("\n=== LOOKING FOR DEPENDENCY GRAPH / PROJECT REFERENCES ===\n");
var projRefs = build.FindChildrenRecursive<Item>().Where(i => i.Name == "ProjectReference").Take(10).ToList();
foreach (var i in projRefs)
    Console.WriteLine($"  ProjectReference: {i.Text}");
