Console.WriteLine($"Found {sourceFiles.Count} embedded source files");
foreach (var sf in sourceFiles.Take(20))
    Console.WriteLine($"  {sf.Name}: {sf.Text?.Substring(0, Math.Min(100, sf.Text?.Length ?? 0))}");

// Look for SourceFilesProjectOutputGroup or similar
Console.WriteLine("\n=== LOOKING FOR PROPERTIES IN Services.csproj ===\n");
var props = build.FindChildrenRecursive<Property>()
    .Where(p => p.Name != null && (p.Name.Contains("Newtonsoft") || p.Name == "PackageReference"))
    .Take(10).ToList();
foreach (var p in props)
    Console.WriteLine($"  {p.Name} = {p.Value}");

// Get all restore messages
Console.WriteLine("\n=== RESTORE MESSAGES (first 30) ===\n");
var restoreMsgs = build.FindChildrenRecursive<Message>()
    .Where(m => m.Text != null && (m.Text.Contains("restore") || m.Text.Contains("Restore") || m.Text.Contains("RESTORE")))
    .Take(30).ToList();
foreach (var m in restoreMsgs)
    Console.WriteLine($"  {m.Text?.Substring(0, Math.Min(200, m.Text.Length))}");

// Try to find what packages ARE referenced by Services.csproj
Console.WriteLine("\n=== ALL AddItem IN Services BUILD ===\n");
var servicesProjects = build.FindChildrenRecursive<Project>().Where(p => p.Name == "Services.csproj").ToList();
foreach (var sp in servicesProjects.Take(2))
{
    var addItems = sp.FindChildrenRecursive<AddItem>().Where(a => a.Name == "PackageReference" || a.Name == "PackageDownload").ToList();
    foreach (var a in addItems)
        foreach (var child in a.Children.OfType<Item>())
            Console.WriteLine($"  {a.Name}: {child.Text}");
}

// Get the CSC command line to see what references were passed
Console.WriteLine("\n=== CSC TASK PARAMS (Services) ===\n");
var cscTasks = build.FindChildrenRecursive<Task>().Where(t => t.Name == "Csc").ToList();
foreach (var csc in cscTasks.Take(1))
{
    var parent = csc.Parent;
    while (parent != null)
    {
        if (parent is Project p) { Console.WriteLine($"  In project: {p.Name}"); break; }
        parent = (parent as TreeNode)?.Parent ?? (parent as BaseNode)?.Parent;
    }
    // Look for References parameter
    var refParams = csc.FindChildrenRecursive<Item>().Where(i => i.Text != null && i.Text.Contains("Newtonsoft")).ToList();
    Console.WriteLine($"  Newtonsoft references in Csc: {refParams.Count}");
    foreach (var r in refParams)
        Console.WriteLine($"    {r.Text}");
}
EOF

